CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('customer','admin','manager') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE settings (`key` VARCHAR(100) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NULL,name VARCHAR(180) NOT NULL,description TEXT,image VARCHAR(1000) DEFAULT '',price DECIMAL(12,2) NOT NULL,available TINYINT(1) DEFAULT 1,featured TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(40) UNIQUE NOT NULL,user_id INT NULL,customer_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(60) NOT NULL,address TEXT,fulfillment ENUM('delivery','pickup') DEFAULT 'delivery',notes TEXT,subtotal DECIMAL(12,2) NOT NULL,delivery_fee DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL,payment_status ENUM('unpaid','pending','paid','refunded') DEFAULT 'unpaid',status ENUM('pending','accepted','preparing','ready','dispatched','completed','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NULL,product_name VARCHAR(180) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,quantity INT NOT NULL,notes VARCHAR(500) DEFAULT '',FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE bookings (id INT AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(40) UNIQUE NOT NULL,user_id INT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(60) NOT NULL,kind ENUM('chef','catering') NOT NULL,event_type VARCHAR(100),event_date DATE NOT NULL,event_time TIME NULL,guests INT NOT NULL,location TEXT NOT NULL,budget VARCHAR(80) DEFAULT '',details TEXT,quote DECIMAL(12,2) NULL,deposit DECIMAL(12,2) DEFAULT 0,status ENUM('inquiry','quoted','awaiting_deposit','confirmed','completed','cancelled') DEFAULT 'inquiry',payment_status ENUM('unpaid','pending','paid','refunded') DEFAULT 'unpaid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(80) UNIQUE NOT NULL,entity_type ENUM('order','booking') NOT NULL,entity_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,currency VARCHAR(4) DEFAULT 'NGN',status ENUM('initialized','success','failed') DEFAULT 'initialized',gateway_response TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE pages (slug VARCHAR(100) PRIMARY KEY,title VARCHAR(200) NOT NULL,body MEDIUMTEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE reviews (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,stars TINYINT NOT NULL,body TEXT NOT NULL,approved TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(180) NOT NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
